// WA logo embedded as a data URI (the PNG uploaded to GitHub was stored as
// base64 text, so the file on disk cannot be trusted as an image source).
// Re-cropped from the original source image so the full WEBAUTOMATE wordmark
// (including the final E) is present, with transparent padding around it.
export const LOGO_PNG_BASE64 = "";
export const LOGO_DATA_URI = "data:image/png;base64," + LOGO_PNG_BASE64;
